
import io
from itertools import groupby
from os.path import basename, splitext
import ast
import tokenize
import warnings
import pygments
from pygments.lexers import get_lexer_by_name
from datasets import load_dataset, Dataset

# StringIO is used by the tokenizer
StringIO = io.StringIO

# Keywords to identify and filter out auto-generated files
AUTO_GENERATED_KEYWORDS = [
    "auto-generated", "autogenerated", "automatically generated",
    "generated by", "do not edit", "don't edit",
]

# Node types for AST parsing
NODE_TYPES = {
    ast.ClassDef: "Class",
    ast.FunctionDef: "Function/Method",
    ast.Module: "Module",
}

def get_comments(s, clean=False):
    "Returns a string including all comments in python code"
    coments = []
    try:
        g = tokenize.generate_tokens(StringIO(s).readline)
        for toknum, tokval, _, _, _ in g:
            if toknum == tokenize.COMMENT:
                coments.append((toknum, tokval))
    except tokenize.TokenError:
        warnings.warn("Tokenization error, no comments extracted")
        return ""
    result = tokenize.untokenize(coments)
    if clean:
        result = result.replace("#", "")
    return result

def parse_docstrings(source):
    """Parse Python source code and yield a tuple of ast node instance, name,
    and docstring for each function/method, class and module."""
    tree = ast.parse(source)
    for node in ast.walk(tree):
        if isinstance(node, tuple(NODE_TYPES)):
            docstring = ast.get_docstring(node)
            yield (node, getattr(node, "name", None), docstring)

def get_docstrings(source, module="<string>"):
    """Parse Python source code from file or string and print docstrings."""
    if hasattr(source, "read"):
        filename = getattr(source, "name", module)
        module = splitext(basename(filename))[0]
        source = source.read()
    
    try:
        docstrings = sorted(
            parse_docstrings(source), key=lambda x: (NODE_TYPES.get(type(x[0])), x[1])
        )
    except (SyntaxError, ValueError):
        warnings.warn("AST parsing failed, no docstrings extracted.")
        return []

    grouped = groupby(docstrings, key=lambda x: NODE_TYPES.get(type(x[0])))
    results = []
    for _, group in grouped:
        for _, name, docstring in group:
            if docstring:
                results.append(docstring)
    return results

def get_text_python(source, comments=True, clean_comments=True):
    """Extract all natural text in source: comments + docstrings."""
    docstrings = "\n".join(get_docstrings(source))
    if comments:
        comments = get_comments(source, clean=clean_comments)
    else:
        comments = ""
    output = docstrings + "\n" + comments
    return output.strip()

def comment_size(text, language):
    """Compute the size of comments in a program (not necessarily python)."""
    try:
        lexer = get_lexer_by_name(language)
        tokens = pygments.lex(text, lexer)
        return sum(len(token) for token_type, token in tokens if token_type in pygments.token.Comment)
    except pygments.util.ClassNotFound:
        warnings.warn(f"Lexer for language '{language}' not found.")
        return 0

def get_nl_ratio(text, language):
    """Get the ratio of comments to code in a program."""
    if not text:
        return 0
    
    if language == "python":
        nl_text = get_text_python(text)
        ratio = len(nl_text) / len(text)
    else:
        ratio = comment_size(text, language) / len(text)
    return ratio

def get_cg_dataset(dataset_name, subset_name, tokenizer, max_source_length, max_target_length):
    """
    Loads, filters, and tokenizes the CodeSearchNet dataset for Seq2Seq fine-tuning.
    """
    print("Loading CodeSearchNet for comment generation...")
    dataset = load_dataset(dataset_name, subset_name, split="train")

    # [cite_start]--- Filtering steps as described in the paper [cite: 1] ---
    # Filter 1: Remove unparsable code
    dataset = dataset.filter(lambda ex: ast.parse(ex['whole_func_string']) is not None)
    # Filter 2: Constrain token length
    dataset = dataset.filter(lambda x: 3 < len(x['whole_func_string'].split()) < 256)
    # Filter 3: Remove special tokens/URLs
    dataset = dataset.filter(lambda x: '(img' not in x['docstring'] and 'http' not in x['docstring'])
    
    # Map to source and target text fields
    def map_to_source_target(example):
        return {
            "source_text": example['func_code_string'],
            "target_text": example['docstring_summary']
        }
    dataset = dataset.map(map_to_source_target, remove_columns=dataset.column_names)

    # Tokenize the dataset
    def preprocess_function(examples):
        model_inputs = tokenizer(
            examples['source_text'], 
            max_length=max_source_length, 
            truncation=True
        )
        labels = tokenizer(
            text_target=examples['target_text'], 
            max_length=max_target_length, 
            truncation=True
        )
        model_inputs["labels"] = labels["input_ids"]
        return model_inputs

    tokenized_dataset = dataset.map(
        preprocess_function, 
        batched=True, 
        desc="Tokenizing dataset"
    )
    return tokenized_dataset


def apply_chat_template(prompt, completion, tokenizer):
    """Applies a chatML-like template for supervised fine-tuning."""
    text = f"<|im_start|>user\n{prompt}<|im_end|>\n<|im_start|>assistant\n{completion}<|im_end|>"
    return {"text": text}

def load_data_for_code_refinement(dataset_name, subset_name):
    """
    Loads and filters The Stack dataset for the code refinement task.
    """
    print("Loading The Stack for code refinement...")
    dataset = load_dataset(dataset_name, data_dir=subset_name, split="train", streaming=True)
    
    def filter_rules(example):
        content = example.get('content')
        if not content:
            return False
            
        lines = content.split('\n')
        num_lines = len(lines)
        if num_lines == 0:
            return False
        
        # --- Filtering logic from the paper ---
        
        # Filter 0: Check for auto-generation keywords in the first 10 lines.
        header = "\n".join(lines[:10]).lower()
        if any(keyword in header for keyword in AUTO_GENERATED_KEYWORDS):
            return False
        
        # Filter 1: Average line length > 100
        if sum(len(line) for line in lines) / num_lines > 100:
            return False
        # Filter 2: Maximum line length > 1000
        if any(len(line) > 1000 for line in lines):
            return False
        # Filter 3: Less than 25% alphanumeric characters
        num_chars = len(content)
        if num_chars == 0:
            return False
        alphanum_chars = sum(c.isalnum() for c in content)
        if alphanum_chars / num_chars < 0.25:
            return False
        
        # Filter 4: Comments-to-code ratio between 0.3 and 0.95
        nl_character_ratio = get_nl_ratio(content, language="python")
        if not (0.3 <= nl_character_ratio <= 0.95):
            return False
        
        return True

    filtered_dataset = dataset.filter(filter_rules)
    
    print("Processing filtered dataset for refinement prompts...")
    processed_examples = []
    
    for example in iter(filtered_dataset):
        content = example['content']
        lines = content.split('\n')
        for i, line in enumerate(lines):
            # A comment followed by a non-empty line of code is a potential training sample
            if line.strip().startswith('#') and (i + 1 < len(lines)) and lines[i+1].strip():
                # Prompt: Code up to the comment + the comment itself
                prompt = "\n".join(lines[:i+1])
                # Completion: The line of code immediately following the comment
                completion = lines[i+1]
                processed_examples.append({"prompt": prompt, "completion": completion})

    print(f"Finished processing. Total samples for code refinement: {len(processed_examples)}")
    return Dataset.from_list(processed_examples)

def build_cr_dataset(dataset_name, subset_name):
    """Builds the dataset for the code refinement task."""
    return load_data_for_code_refinement(dataset_name, subset_name)
